import { procedure, prefix, post, initSegment, operation } from "vovk";
import { Bench } from "tinybench";

function noopDecorator(arg?: KnownAny) {
  return function <T>(
    target: KnownAny,
    propertyKey: string,
    descriptor?: TypedPropertyDescriptor<T>,
  ): KnownAny {
    return descriptor;
  };
}

function noopClassDecorator(message?: string) {
  return function <T extends { new (...args: KnownAny[]): {} }>(
    constructor: T,
  ) {
    return constructor;
  };
}

const bench = new Bench({ time: 100 });

bench.add("Cold start for 1 controllers", async () => {
  const controllers: Record<string, Function> = {};
  @prefix("one/0")
  class One0Controller {
    @operation({
      summary: "Create",
    })
    @post("{id}")
    static create = procedure({
      handle: () => null,
    });
  }

  controllers["One0Controller"] = One0Controller;

  initSegment({
    segmentName: "",
    emitSchema: true,
    controllers,
  });
});

bench.add("No-op decorators for 1 classes", async () => {
  const controllers: Record<string, Function> = {};
  @noopClassDecorator()
  class One0Controller {
    @noopDecorator({
      summary: "Create",
    })
    @noopDecorator("{id}")
    static create = (_req: unknown, params: KnownAny) => {
      return null;
    };
  }
});

